import { COLORS, FUNNEL, HEALTH, withAlpha } from '@/design-system';
import { CATEGORICAL } from '../../_constants/colors';
import { formatBRL } from '../../_utils';

export const HEALTH_STACK_TEAM_ALPHA = 0.48;
export const HEALTH_STACK_ZERO_LINE_PX = 2;
export const HEALTH_STACK_GAP_PX = 4;
export const HEALTH_STACK_FALLBACK_INNER_HEIGHT = 220;

export type HealthStackMetricKey = 'cad30d' | 'cad90d' | 'volume' | 'pctReceita' | 'conv';

export const HEALTH_STACK_TEAM_KEY = 'teamAvg' as const;
export const HEALTH_STACK_GAP_KEY = '_gap' as const;
export const HEALTH_STACK_BROKER_KEY = 'broker' as const;

export const HEALTH_STACK_SCALE_MAX: Record<HealthStackMetricKey, number> = {
  cad30d: 30,
  cad90d: 80,
  volume: 20,
  pctReceita: 100,
  conv: 100,
};

export type HealthStackUnit = 'count' | 'volume' | 'percent';

export type ProfileHealthValues = Record<HealthStackMetricKey, number>;

export type ProfileHealthChartRow = {
  name: string;
  metricKey: HealthStackMetricKey;
  teamAvgValue: number;
  brokerValue: number;
  reference: number;
  [HEALTH_STACK_TEAM_KEY]: number;
  [HEALTH_STACK_GAP_KEY]: number;
  [HEALTH_STACK_BROKER_KEY]: number;
};

export type ProfileHealthMetricDef = {
  key: HealthStackMetricKey;
  short: string;
  unit: HealthStackUnit;
  color: string;
  teamFill: string;
  brokerFill: string;
};

const HEALTH_STACK_COLOR: Record<HealthStackMetricKey, string> = {
  cad30d: COLORS.brand,
  cad90d: COLORS.brandDeep,
  volume: CATEGORICAL.teal,
  pctReceita: HEALTH.warningDeep,
  conv: FUNNEL.completed,
};

export const HEALTH_STACK_METRICS: readonly ProfileHealthMetricDef[] = (
  [
    { key: 'cad30d', short: 'Cad 30d', unit: 'count' },
    { key: 'cad90d', short: 'Cad 90d', unit: 'count' },
    { key: 'volume', short: 'Volume', unit: 'volume' },
    { key: 'pctReceita', short: '% Desemb.', unit: 'percent' },
    { key: 'conv', short: 'Conv.', unit: 'percent' },
  ] as const
).map((metric) => {
  const color = HEALTH_STACK_COLOR[metric.key];
  return {
    ...metric,
    color,
    teamFill: withAlpha(color, HEALTH_STACK_TEAM_ALPHA),
    brokerFill: color,
  };
});

export function toFiniteNonNegative(value: number): number {
  if (!Number.isFinite(value) || value < 0) {
    return 0;
  }
  return value;
}

export function toHealthPxRatio(px: number, innerHeight: number): number {
  const safePx = toFiniteNonNegative(px);
  if (!Number.isFinite(innerHeight) || innerHeight <= 0) {
    return 0;
  }
  return safePx / innerHeight;
}

export function toHealthSegmentRatio(
  value: number,
  scaleMax: number,
  innerHeight: number,
): number {
  const safe = toFiniteNonNegative(value);
  if (safe === 0) {
    return toHealthPxRatio(HEALTH_STACK_ZERO_LINE_PX, innerHeight);
  }
  const max = toFiniteNonNegative(scaleMax);
  if (max === 0) {
    return toHealthPxRatio(HEALTH_STACK_ZERO_LINE_PX, innerHeight);
  }
  return Math.min(safe / max, 1);
}

export function resolveHealthPlotInnerHeight(plotHeight: number, marginY: number): number {
  const inner = plotHeight - marginY;
  if (!Number.isFinite(inner) || inner <= 0) {
    return HEALTH_STACK_FALLBACK_INNER_HEIGHT;
  }
  return inner;
}

export function formatHealthMetricValue(unit: HealthStackUnit, value: number): string {
  const safe = toFiniteNonNegative(value);
  if (unit === 'volume') {
    return formatBRL(safe);
  }
  if (unit === 'percent') {
    return `${safe.toFixed(0)}%`;
  }
  return String(Math.round(safe));
}

export function isProfileHealthEmpty(
  values: ProfileHealthValues,
  teamAvg: ProfileHealthValues,
): boolean {
  return HEALTH_STACK_METRICS.every((metric) => {
    return (
      toFiniteNonNegative(values[metric.key]) === 0 &&
      toFiniteNonNegative(teamAvg[metric.key]) === 0
    );
  });
}

export function buildProfileHealthChartData(
  values: ProfileHealthValues,
  teamAvg: ProfileHealthValues,
  innerHeight = HEALTH_STACK_FALLBACK_INNER_HEIGHT,
): ProfileHealthChartRow[] {
  const gapRatio = toHealthPxRatio(HEALTH_STACK_GAP_PX, innerHeight);

  return HEALTH_STACK_METRICS.map((metric) => {
    const brokerValue = toFiniteNonNegative(values[metric.key]);
    const teamAvgValue = toFiniteNonNegative(teamAvg[metric.key]);
    const reference = HEALTH_STACK_SCALE_MAX[metric.key];

    return {
      name: metric.short,
      metricKey: metric.key,
      teamAvgValue,
      brokerValue,
      reference,
      [HEALTH_STACK_TEAM_KEY]: toHealthSegmentRatio(teamAvgValue, reference, innerHeight),
      [HEALTH_STACK_GAP_KEY]: gapRatio,
      [HEALTH_STACK_BROKER_KEY]: toHealthSegmentRatio(brokerValue, reference, innerHeight),
    };
  });
}

export function resolveHealthStackFill(
  point: Record<string, unknown>,
  segment: typeof HEALTH_STACK_TEAM_KEY | typeof HEALTH_STACK_BROKER_KEY,
): string {
  const metric = HEALTH_STACK_METRICS.find((item) => item.key === point.metricKey);
  if (!metric) {
    return COLORS.brand;
  }
  return segment === HEALTH_STACK_TEAM_KEY ? metric.teamFill : metric.brokerFill;
}

export function buildProfileHealthLegendItems(
  values: ProfileHealthValues,
  teamAvg: ProfileHealthValues,
) {
  return HEALTH_STACK_METRICS.map((metric) => {
    const brokerValue = toFiniteNonNegative(values[metric.key]);
    const teamAvgValue = toFiniteNonNegative(teamAvg[metric.key]);
    return {
      key: metric.key,
      short: metric.short,
      color: metric.color,
      value: formatHealthMetricValue(metric.unit, brokerValue),
      teamValue: formatHealthMetricValue(metric.unit, teamAvgValue),
      isAboveTeam: brokerValue >= teamAvgValue,
    };
  });
}

export function buildProfileHealthTooltipRows(point: Record<string, unknown>) {
  const metric = HEALTH_STACK_METRICS.find((item) => item.key === point.metricKey);
  if (!metric) {
    return [];
  }

  return [
    {
      label: 'Broker',
      value: formatHealthMetricValue(metric.unit, Number(point.brokerValue ?? 0)),
      color: metric.brokerFill,
    },
    {
      label: 'Média da equipe',
      value: formatHealthMetricValue(metric.unit, Number(point.teamAvgValue ?? 0)),
      color: metric.teamFill,
    },
  ];
}

export function buildProfileHealthAriaLabel(
  values: ProfileHealthValues,
  teamAvg: ProfileHealthValues,
): string {
  if (isProfileHealthEmpty(values, teamAvg)) {
    return 'Perfil de saúde: sem dados para comparar com a equipe';
  }

  const parts = HEALTH_STACK_METRICS.map((metric) => {
    const broker = formatHealthMetricValue(metric.unit, values[metric.key]);
    const avg = formatHealthMetricValue(metric.unit, teamAvg[metric.key]);
    return `${metric.short} ${broker} vs média ${avg}`;
  });

  return `Perfil de saúde: ${parts.join(', ')}`;
}

